class Solution {
    public int[] pairForPrice(int[] balances, int price) {
        // Partner balance = price - own balance
        // seen (balance to index of earlier cards)
        // One pass, so each pair is found at its later card
        Map<Integer, Integer> seen = new HashMap<>();
        // each card with its index
        for (int j = 0; j < balances.length; j++) {
            // earlier card holding price - balance (null = no partner yet)
            Integer partner = seen.get(price - balances[j]);
            // earlier index first
            if (partner != null) return new int[]{partner, j};
            // store after lookup, ensuring card doesn't pair itself
            seen.put(balances[j], j);
        }
        return new int[0];  // no pair
    }
}

