    vector<int> pairForPrice(vector<int>& balances, int price) {
        // Partner balance = price - own balance
        // seen (balance to index of earlier cards)
        // One pass, so each pair is found at its later card
        unordered_map<int, int> seen;
        // reserve up front, avoiding rehash
        seen.reserve(balances.size() * 2);
        // each card with its index
        for (int j = 0; j < (int)balances.size(); j++) {
            // earlier card holding price - balance (end = no partner yet)
            auto partner = seen.find(price - balances[j]);
            // earlier index first
            if (partner != seen.end()) return {partner->second, j};
            // store after lookup, ensuring card doesn't pair itself
            seen[balances[j]] = j;
        }
        return {};  // no pair
    }
};

