class Solution {
    public int[] pairForPrice(int[] balances, int price) {
        // Sort card indexes by balance
        // Pointers squeeze inward from lowest and highest balance
        // Too small sum = low card has no partner left; too big = high card has none
        int n = balances.length;
        // card indexes, lowest balance first
        Integer[] order = new Integer[n];
        for (int i = 0; i < n; i++) order[i] = i;
        Arrays.sort(order, (a, b) -> Integer.compare(balances[a], balances[b]));
        int lo = 0, hi = n - 1;
        while (lo < hi) {
            // sum of current low and high balances (long, no int overflow)
            long total = (long) balances[order[lo]] + balances[order[hi]];
            if (total == price) {
                int a = order[lo], b = order[hi];
                // sorting shuffled indexes, so put smaller first
                return new int[]{Math.min(a, b), Math.max(a, b)};
            }
            // low card too small even with highest left
            if (total < price) lo++;
            // high card too big even with lowest left
            else hi--;
        }
        // unreachable
        return new int[0];
    }
}

