        vector<int> order(n);
        iota(order.begin(), order.end(), 0);
        sort(order.begin(), order.end(), [&](int a, int b) { return balances[a] < balances[b]; });
        int lo = 0, hi = n - 1;
        while (lo < hi) {
            // sum of current low and high balances (long long, no int overflow)
            long long total = (long long)balances[order[lo]] + balances[order[hi]];
            // sorting shuffled indexes, so put smaller first
            if (total == price) return {min(order[lo], order[hi]), max(order[lo], order[hi])};
            // low card too small even with highest left
            if (total < price) lo++;
            // high card too big even with lowest left
            else hi--;
        }
        return {};  // unreachable
