class Solution {
    public int longestFreshRun(String plays) {
        // Window [left, right] with no repeats
        // Earlier copy of c inside window = repeat, so jump left just past it
        // Best = widest window seen at any right
        // last index of each ASCII char
        int[] last = new int[128];
        // -1 = unseen
        Arrays.fill(last, -1);
        int best = 0, left = 0;
        for (int right = 0; right < plays.length(); right++) {
            char c = plays.charAt(right);
            // earlier copy inside window, so jump past it
            if (last[c] >= left) left = last[c] + 1;
            // remember latest index of c
            last[c] = right;
            best = Math.max(best, right - left + 1);
        }
        return best;
    }
}

