class Solution {
    public int longestFreshRun(String plays) {
        // Window [left, right] with no repeats, kept as set
        // Duplicate = drop from left until old copy leaves
        // Each play enters and leaves set at most once
        // chars currently in window
        Set<Character> window = new HashSet<>();
        int best = 0, left = 0;
        for (int right = 0; right < plays.length(); right++) {
            char c = plays.charAt(right);
            // drop from left until old copy of c is gone
            while (window.contains(c)) window.remove(plays.charAt(left++));
            // window repeat-free again, so c fits
            window.add(c);
            best = Math.max(best, window.size());
        }
        return best;
    }
}

