class Solution {
    public String shortestStretch(String street, String shopping) {
        // Window [left, right] over street
        // Grow right until window covers list, then shrink left while still covered
        // Keep shortest covered window
        // need[ch] (count of ch still needed; negative = extras)
        // missing (list items not in window yet; 0 = covered)
        // Shrinking at each right finds shortest covered window ending there
        // one count per ASCII char
        int[] need = new int[128];
        for (char ch : shopping.toCharArray()) need[ch]++;
        int missing = shopping.length(), left = 0;
        // MAX_VALUE = nothing found yet
        int bestLen = Integer.MAX_VALUE, bestStart = 0;
        for (int right = 0; right < street.length(); right++) {
            char ch = street.charAt(right);
            // counts only if still needed
            if (need[ch] > 0) missing--;
            need[ch]--;
            // covered, so record then shrink
            while (missing == 0) {
                if (right - left + 1 < bestLen) {
                    bestLen = right - left + 1;
                    bestStart = left;
                }
                char dropped = street.charAt(left++);
                need[dropped]++;
                // dropped needed item, so no longer covered
                if (need[dropped] > 0) missing++;
            }
        }
        // never covered
        if (bestLen == Integer.MAX_VALUE) return "";
        return street.substring(bestStart, bestStart + bestLen);
    }
}

