class Solution {
    public String shortestStretch(String street, String shopping) {
        // Try every start, extend right until list is covered
        // First cover = shortest from that start, so stop there
        // Only strictly shorter replaces best, so earliest start wins
        // count of each item needed (one slot per ASCII char)
        int[] startNeed = new int[128];
        // each needed item
        for (char c : shopping.toCharArray()) startNeed[c]++;
        // "" = nothing covered yet
        String best = "";
        for (int i = 0; i < street.length(); i++) {
            // copy, so each start begins with full counts (negative = extras)
            int[] need = startNeed.clone();
            // items not covered yet (0 = covered)
            int missing = shopping.length();
            for (int j = i; j < street.length(); j++) {
                char c = street.charAt(j);
                // item still needed, so counts toward cover
                if (need[c] > 0) missing--;
                need[c]--;
                // covered, so score this start
                if (missing == 0) {
                    // strictly shorter (or first found), so earliest wins ties
                    if (best.isEmpty() || j - i + 1 < best.length()) best = street.substring(i, j + 1);
                    break;
                }
            }
        }
        return best;
    }
}

